		t.Fatal(snapshot, len(wire))
	}
}", "independent_literal_expectations": "The application SHALL persist valid automatic or explicit-zero authored keys through the existing owner. Missing requested families or copied event counts SHALL use at most one same-profile output repair, retain the clean baseline and emit no completed candidate/manifest. Independent literal input/output/arithmetic assertions use constructed examples. Native tests retain actual PostgreSQL/MinIO and production dispatch; the remote model response is an explicit fixture."}

